import {isDeepStrictEqual} from 'node:util';
import {randomUUID} from 'node:crypto';
import {Client} from 'pg';
import {writeFile} from 'node:fs/promises';
import {join} from 'node:path';
import type {Browser,BrowserContext} from 'playwright';
import type {CurrentSession} from '../../lib/server/auth/sessions';
import {submitProfileCommand} from '../../lib/server/profiles/service';
import {query} from '../../lib/server/db/client';
import {inspectSolutionKnowledge,searchSolutionPatterns} from '../../lib/server/knowledge/workspace-patterns/repository';
import {getLearningContribution,getAdoptionPatterns} from '../../lib/server/learning/customer-adoption/repository';
import {fitDimensions} from '../../lib/contracts/solution-patterns';
export async function runOrdinaryKnowledgeNativeChecks(input:{browser:Browser;origin:string;ownerDatabaseUrl:string;author:CurrentSession;admin:CurrentSession;output:string}){
 if(process.env.TURAS_OPERATIONS_NATIVE_FIXTURE!=='1'||process.env.TURAS_ALLOW_LIVE_MODEL_TESTS==='1'||process.env.AI_GATEWAY_API_KEY||process.env.VERCEL_OIDC_TOKEN||!/^\/turas_test_010_eval_[a-f0-9]{12}$/.test(new URL(input.ownerDatabaseUrl).pathname)||!process.env.TURAS_ENVIRONMENT_ID?.startsWith('test-'))throw Error('Owned unpaid knowledge fixture required');
 const {browser,origin,author,admin,output}=input,owner=new Client({connectionString:input.ownerDatabaseUrl});await owner.connect();
 const accountId=randomUUID(),patternId=randomUUID(),applicationId=randomUUID(),paragraph='A bounded isolated execution workflow with explicit operating ownership.',reviewAfter=new Date(Date.now()+60*86400000).toISOString().slice(0,10);
 try{await owner.query("INSERT INTO customer_references(id,workspace_id,display_name,synthetic) VALUES($1,$2,'Native knowledge fixture',false)",[accountId,admin.workspaceId]);await owner.query('CREATE TABLE ordinary_knowledge_native_cases(key text PRIMARY KEY,account_id uuid NOT NULL,read_tool text NOT NULL,write_tool text NOT NULL,command jsonb NOT NULL);GRANT SELECT ON ordinary_knowledge_native_cases TO turas_runtime');
 const journey={title:'Measured execution pilot',summary:'Reviewed native fixture measurement and operating handoff.',scope:'A bounded synthetic pilot',kind:'outcome',stage:'Adopt',observedAt:'2026-09-30',reviewAfter,confidence:'high',source:{kind:'note',reference:'Synthetic measured note',url:'',excerpt:'Synthetic approved customer observation.'},impact:{metric:'Weekly active administrators',unit:'%',baseline:20,current:40,target:50,direction:'increase',periodStart:'2026-09-01',periodEnd:'2026-09-30',basis:'measured',attribution:'Only this bounded synthetic pilot was measured.'}};
 const proposed=await submitProfileCommand(author,accountId,{action:'propose_record',requestKey:randomUUID(),requestedAudience:'delivery',dataCategory:'delivery_context',payload:{kind:'claim',text:journey.summary,sourceType:'manual',legacyJourney:journey}}) as {revisionId:string;recordId:string};
 const head=(await owner.query('SELECT v.content_digest,r.version FROM profile_revisions v JOIN profile_records r ON r.id=v.record_id WHERE v.id=$1',[proposed.revisionId])).rows[0];
 await submitProfileCommand(admin,accountId,{action:'accept_revision',requestKey:randomUUID(),revisionId:proposed.revisionId,digest:head.content_digest,expectedRecordVersion:Number(head.version),expectedAcceptedRevisionId:null,rationale:'Independently reviewed the exact native synthetic measurement source.'});
 const pattern={title:'Isolated execution handoff',problem:paragraph,prerequisites:paragraph,approach:paragraph,delivery:paragraph,processAndAdoption:paragraph,limitations:paragraph,alternatives:paragraph,lessons:paragraph,outcome:{basis:'measured',description:paragraph,measurementLimits:'Only a bounded pilot with a reviewed baseline was measured.'},reviewAfter};
 const cases=[{key:'include',read:'get_learning_contribution',write:'review_learning_contribution',command:{action:'include',requestId:randomUUID(),quarter:'2026-Q3',expectedVersion:0,rationale:'Explicitly approve this exact measurement for restricted portfolio reuse.',sourceRecordId:proposed.revisionId,contribution:{baselineActive:2,currentActive:4,eligibleAdministrators:10,intervention:'enablement_and_handoff',definitionAndSamePopulationConfirmed:true}}},
 {key:'publish',read:'get_solution_knowledge',write:'review_solution_pattern',command:{action:'publish',patternId,requestId:randomUUID(),expectedVersion:0,rationale:'Review the complete generalized derivative and its exact redaction attestation.',sourceRecordId:proposed.revisionId,pattern,attestation:{generalizedContentReviewed:true,workspaceReuseApproved:true,outcomeBasisVerified:true}}},
 {key:'apply',read:'get_solution_knowledge',write:'review_solution_application',command:{action:'approve',applicationId,requestId:randomUUID(),expectedVersion:0,pattern:{patternId,version:1},targetContextHash:'0'.repeat(64),fit:fitDimensions.map(dimension=>({dimension,status:'compatible',evidence:paragraph,adaptation:paragraph})),validationPlan:paragraph,rationale:paragraph,targetApprovalConfirmed:true}},
 {key:'revoke',read:'get_learning_contribution',write:'review_learning_contribution',command:{action:'revoke',requestId:randomUUID(),quarter:'2026-Q3',expectedVersion:1,rationale:'Withdraw the separate portfolio reuse consent.'}},
 {key:'withdraw',read:'get_solution_knowledge',write:'review_solution_pattern',command:{action:'withdraw',patternId,requestId:randomUUID(),expectedVersion:1,rationale:'Withdraw the workspace derivative while retaining immutable history.'}}];
 for(const item of cases)await owner.query('INSERT INTO ordinary_knowledge_native_cases VALUES($1,$2,$3,$4,$5)',[item.key,accountId,item.read,item.write,item.command]);
 const identity={...admin,userId:admin.principalId,environmentId:process.env.TURAS_ENVIRONMENT_ID!},contexts:BrowserContext[]=[];
 const until=async(check:()=>Promise<boolean>,label:string)=>{const end=Date.now()+60000;while(Date.now()<end){if(await check())return;await new Promise(r=>setTimeout(r,100));}throw Error('Knowledge native timeout: '+label);};
 async function login(){const context=await browser.newContext({baseURL:origin,viewport:{width:1440,height:1000}});contexts.push(context);const r=await context.request.post('/api/auth/login',{headers:{origin},data:{username:'mcteer',password:process.env.TURAS_DEMO_PASSWORD}});if(!r.ok())throw Error('Knowledge owner login failed');return {context,headers:{origin,'x-csrf-token':(await r.json()).data.csrfToken}};}
 try{for(const item of cases){
  const actor=await login(),operationId=randomUUID();const created=await actor.context.request.post('/api/conversations',{headers:actor.headers,data:{requestKey:operationId,title:'Synthetic native knowledge '+item.key}});if(!created.ok())throw Error('Knowledge chat creation failed');const id=(await created.json()).data.id;let native='';
  for(let i=0;i<5;i++){const r=await actor.context.request.post('/eve/v1/session',{headers:{...actor.headers,'x-turas-conversation-id':id},data:{operationId}});if(r.ok()){native=(await r.json()).sessionId;break;}if(r.status()!==409)throw Error('Knowledge binding failed');await new Promise(r=>setTimeout(r,500));}if(!native)throw Error('Knowledge binding unconfirmed');
  const page=await actor.context.newPage();await page.goto('/s/'+id,{waitUntil:'domcontentloaded'});await page.getByRole('textbox',{name:'Message Turi'}).fill('Knowledge native: '+item.key);await page.getByRole('button',{name:'Send message',exact:true}).click();await page.getByRole('region',{name:'Your decision'}).waitFor({timeout:60000});const preview=JSON.parse(await page.getByRole('region',{name:'Your decision'}).locator('pre').innerText());if(preview.accountId!==accountId||preview.command.requestId!==item.command.requestId||preview.command.action!==item.command.action)throw Error('Exact proposed knowledge input not shown');if('sourceRecordId' in item.command&&preview.command.sourceRecordId!==proposed.revisionId)throw Error('Exact source not shown for reuse approval');if(item.key==='publish'&&!isDeepStrictEqual(preview.command.pattern,pattern))throw Error('Full generalized derivative not reviewable');if(item.key==='apply'&&(!preview.command.fit||preview.command.fit.length!==6||preview.command.targetContextHash==='0'.repeat(64)))throw Error('Full target fit/current context not reviewable');
  const table=item.write==='review_learning_contribution'?'customer_adoption_contributions':item.write==='review_solution_pattern'?'workspace_solution_patterns':'workspace_solution_applications';
  if(Number((await query(`SELECT count(*) AS n FROM ${table} WHERE request_id=$1`,[item.command.requestId])).rows[0].n)!==0)throw Error('Knowledge write preceded human approval');
  const fresh=await login(),approved=await fresh.context.newPage();await approved.goto('/s/'+id,{waitUntil:'domcontentloaded'});const freshPreview=JSON.parse(await approved.getByRole('region',{name:'Your decision'}).locator('pre').innerText());if(!isDeepStrictEqual(freshPreview,preview))throw Error('Fresh owner exact knowledge proposal changed');await page.close();if(['include','publish','apply'].includes(item.key)){await approved.setViewportSize({width:390,height:844});if(await approved.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Knowledge action preview mobile overflow');await approved.screenshot({path:join(output,'knowledge-'+item.key+'-mobile.png'),fullPage:true});await approved.setViewportSize({width:1440,height:1000});}await approved.getByRole('region',{name:'Your decision'}).getByRole('button',{name:'Approve',exact:true}).click();await approved.getByText(`Knowledge native ${item.key} recorded.`,{exact:true}).waitFor({timeout:60000});
  await until(async()=>Number((await query(`SELECT count(*) AS n FROM ${table} WHERE request_id=$1`,[item.command.requestId])).rows[0].n)===1,'immutable '+item.key+' receipt');await approved.reload({waitUntil:'domcontentloaded'});await approved.getByText(`Knowledge native ${item.key} recorded.`,{exact:true}).waitFor();
  if(item.key==='apply'&&(await inspectSolutionKnowledge(identity,accountId)).applications[0]?.eligibility!=='current')throw Error('Native approved adaptation not current');
  if(!(await fresh.context.request.post('/eve/v1/session/'+native+'/reset',{headers:fresh.headers,data:{reason:'Owned knowledge native case complete'}})).ok())throw Error('Knowledge retirement unconfirmed');await approved.close();
  console.log(JSON.stringify({stage:'knowledge_'+item.key+'_passed'}));
 }
 if((await getLearningContribution(identity,accountId,'2026-Q3')).action!=='revoke')throw Error('Reuse consent not revoked');if((await searchSolutionPatterns(identity,accountId,'isolated execution')).patterns.length)throw Error('Withdrawn pattern still reusable');if((await inspectSolutionKnowledge(identity,accountId)).applications[0]?.eligibility!=='pattern_unavailable')throw Error('Withdrawal did not invalidate application');
 const latest=(await owner.query('SELECT version FROM profile_records WHERE id=$1',[proposed.recordId])).rows[0];await submitProfileCommand(admin,accountId,{action:'retract_revision',requestKey:randomUUID(),revisionId:proposed.revisionId,expectedRecordVersion:Number(latest.version),rationale:'Retract the underlying synthetic measurement to check source invalidation.'});
 if((await getAdoptionPatterns(identity,'2026-Q3')).status!=='insufficient_evidence')throw Error('Small/revoked cohort released');
 const receipt={actualEveRuntime:true,CLIWebKit:true,paidProviderCalls:0,actualRootReadAndReviewTools:cases.map(x=>x.write),beforeApprovalWrites:0,freshOwnerLoginApprovals:5,reloadedHistory:true,immutableIdenticalRequestReceipts:true,withdrawalInvalidatedApplication:true,revokedReuseSuppressed:true,sourceRetractionChecked:true};await writeFile(join(output,'knowledge-receipt.json'),JSON.stringify(receipt,null,2),{mode:0o600});return receipt;
 }finally{for(const context of contexts)await context.close();}
 }finally{await owner.end();}
}
